      const promoted = await approveLead(lead.id, {});
      if (promoted.ok) {
        saved += 1;
        if (evidence.length < 20) evidence.push(lead.sourceUrl);
      } else {
        duplicates += 1;
      }
      if (saved >= input.targetCount) break;
    }
  }

  return { discovered, saved, duplicates, evidence, source };
}

