(r.byEngine||[]).forEach(e=>{
  console.log('  '+e.kind+' | status: '+e.lastStatus+' | runs: '+e.runCount+' | evidence: '+e.withEvidence+'/'+e.runCount+' | '+(e.lastSummary||'').slice(0,60));
});" && echo "" && echo "=== Dashboard: CRM traceability (investor → SEC source) ===" && curl -s -H "Authorization: Bearer $TOKEN" "https://api.ivxholding.com/api/ivx/investors?limit=3" -o /tmp/dash_crm.json && node -e "
